import {buildPortfolio,selectAssets,queryPortfolio,environmentMatrix,describeEvidence,environmentOrder} from './model.js';
import {runtimes,operators} from '../version-search.mjs';

export const enterpriseViews={
  applications:['▦','Applications','Explore software across your business applications and deployed environments.'],
  deployed:['⌕','Deployed versions','Find the exact runtime or library recorded for each deployed workload.'],
  matrix:['▥','Environment matrix','Compare deployed versions across dev, UAT, and production.'],
  sources:['⇆','Data sources','Inspect the simulated API snapshots and how their records are linked.'],
};
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tag=(text,kind='')=>`<span class="tag ${kind}">${esc(text)}</span>`;
const panel=(title,body,right='')=>`<section class="panel"><div class="panel-head"><h2>${title}</h2>${right}</div>${body}</section>`;
const btn=(label,attrs='',className='text-link quiet')=>`<button type="button" class="${className}" ${attrs}>${label}</button>`;
const envName=e=>({dev:'DEV',uat:'UAT',prod:'PROD',stage:'STAGE',test:'TEST',unassigned:'UNASSIGNED'})[e]||e.toUpperCase();
const statGrid=items=>`<div class="stats">${items.map(([label,value,sub,icon])=>`<div class="stat"><span class="stat-label">${label}</span><span class="stat-icon">${icon}</span><div class="stat-num">${value}</div><small>${sub}</small></div>`).join('')}</div>`;
const displayRuntime=c=>runtimes.find(r=>r.id===c.runtime)?.label||c.name;
const shortDigest=value=>value?value.length>24?value.slice(0,18)+'…'+value.slice(-6):value:'Not observed';

export function createEnterprise({onChange,openDialog,inspectSbom}){
  let fleet=null,error='',loading=true,source='servicenow',sourceRaw=false;
  let request={appId:'all',environment:'all',projectId:'all',kindFilter:'all',kind:'runtime',runtime:'python',name:'requests',match:'exact',operator:'any',target:'3.11'};
  let draft=false,status='all',page=0,lastView='applications';
  const result=()=>queryPortfolio(fleet,request);
  const queryLabel=()=>`${request.kind==='runtime'?runtimes.find(r=>r.id===request.runtime)?.label:request.name} ${operators.find(o=>o.id===request.operator)?.symbol||''} ${request.operator==='any'?'· all recorded versions':request.target}`;
  const option=(value,label,current)=>`<option value="${esc(value)}" ${String(value)===String(current)?'selected':''}>${esc(label)}</option>`;
  function scopes(matrix=false){
    const projects=[...fleet.projectMap.values()].filter(p=>request.appId==='all'||fleet.appMap.get(request.appId)?.projectIds.includes(p.id));
    return `<div class="fleet-scope"><label>Business application<select id="fleet-app">${option('all','All applications',request.appId)}${fleet.apps.map(a=>option(a.id,a.name,request.appId)).join('')}${option('unassigned','Unassigned assets',request.appId)}</select></label>${matrix?`<div class="all-env-label">Comparing all environments<br><span>DEV → UAT → PROD</span></div>`:`<label>Environment<select id="fleet-env">${option('all','All environments',request.environment)}${[...new Set(fleet.assets.map(a=>a.environment))].sort((a,b)=>environmentOrder.indexOf(a)-environmentOrder.indexOf(b)).map(e=>option(e,envName(e),request.environment)).join('')}</select></label>`}<label>Service / GitLab project<select id="fleet-project">${option('all','All services',request.projectId)}${projects.map(p=>option(p.id,p.name,request.projectId)).join('')}</select></label><label>AWS resource<select id="fleet-kind">${option('all','All resource types',request.kindFilter)}${['ECS','Lambda','EC2'].map(k=>option(k,k,request.kindFilter)).join('')}</select></label></div>`;
  }
  function banner(){return `<div class="simulation-banner"><div><span class="simulation-pill">SIMULATED</span><span>ServiceNow <i>→</i> GitLab <i>→</i> AWS</span></div><span>Fictional records · no live connections</span></div>`;}
  function applications(){
    const assets=selectAssets(fleet,request),shown=fleet.apps.filter(a=>request.appId==='all'||request.appId===a.id);
    return banner()+scopes()+statGrid([
      ['Business applications',shown.length,`${fleet.apps.length} in the simulated portfolio`,'▦'],
      ['GitLab services',new Set(assets.map(a=>a.project?.id).filter(Boolean)).size,'Mapped to business applications','⌘'],
      ['Running workloads',assets.length,'ECS containers, Lambda versions, EC2 hosts','⬡'],
      ['Missing artifact evidence',assets.filter(a=>a.coverage==='gap').length,'Review before drawing version conclusions','?'],
    ])+panel('Ask a deployment question',`<div class="fleet-question"><div><h3>Which environments still have an older runtime?</h3><p>Select a question to search the currently scoped assets, with the build and asset evidence attached.</p></div><div class="fleet-quick">${btn('Python &lt; 3.11','data-fleet-preset="python"','button')}${btn('Node.js &lt; 20','data-fleet-preset="node"','button')}${btn('Where is Log4j?','data-fleet-preset="log4j"','button')}</div></div>`)+`<div class="application-grid">${shown.map(a=>{
      const records=assets.filter(x=>x.app?.id===a.id),gaps=records.filter(x=>x.coverage==='gap').length;
      return `<article class="application-card"><div class="application-card-top"><span class="app-number">${esc(a.number)}</span>${tag(a.criticality.startsWith('1')?'Business critical':'Business application')}</div><h2>${esc(a.name)}</h2><p>${esc(a.description)}</p><div class="app-owner">${esc(a.owner)} <span>${records.length} workloads · ${a.projectIds.length} services</span></div><div class="app-environments">${environmentOrder.map(e=>{const envAssets=records.filter(x=>x.environment===e),versions=[...new Set(envAssets.flatMap(x=>x.components.filter(c=>c.runtime).map(c=>`${displayRuntime(c)} ${c.version}${c.precision==='family'?' (family)':''}`)))];return `<div><b class="environment-dot ${e}">${envName(e)}</b><span>${versions.length?esc(versions.join(' · ')):envAssets.length?'Version evidence missing':'No assets in scope'}</span></div>`}).join('')}</div><div class="app-card-footer"><span>${gaps?tag(gaps+' evidence gap'+(gaps===1?'':'s'),'medium'):tag('Inventory linked')}${records.some(x=>x.rolloutDifference)?' '+tag('Mixed rollout','medium'):''}</span>${btn('Explore versions →',`data-fleet-app="${a.id}"`)}</div></article>`;
    }).join('')}</div>`+panel('Deployed asset inventory',assetTable(assets),`<a class="text-link" href="#deployed">Search all versions ↗</a>`);
  }
  function assetTable(assets){return `<div class="table-wrap"><table><thead><tr><th>Application / service</th><th>Environment</th><th>AWS asset</th><th>Version evidence</th><th>Trace</th></tr></thead><tbody>${assets.map(a=>`<tr><td><strong>${esc(a.service)}</strong><small>${esc(a.app?.name||'Unassigned application')}</small></td><td>${tag(envName(a.environment),a.environment==='prod'?'prod':'')}</td><td>${tag(a.kind)}<small>${esc(a.resourceId.split('/').at(-1).split(':').at(-1))} · ${esc(a.region)}</small></td><td>${tag(describeEvidence(a),a.coverage==='gap'?'medium':a.coverage==='host'?'unknown':'')}<small>${a.rolloutDifference?'Rollout target differs':a.kind==='Lambda'?'Runtime patch not supplied':a.coverage==='host'?'Application usage unverified':esc(shortDigest(a.digest))}</small></td><td>${btn('Inspect →',`data-fleet-asset="${esc(a.id)}"`)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">No running workloads in this scope.</td></tr>'}</tbody></table></div>`;}
  function searchForm(){return `<form id="fleet-query"><div class="version-fields"><label>Component type<select id="fleet-component-kind">${option('runtime','Language / runtime',request.kind)}${option('package','Library / package',request.kind)}</select></label>${request.kind==='runtime'?`<label>Language / runtime<select id="fleet-runtime">${runtimes.map(r=>option(r.id,r.label,request.runtime)).join('')}</select></label>`:`<label>Package name or URL<input id="fleet-name" list="fleet-packages" value="${esc(request.name)}" placeholder="e.g. requests, log4j-core"><datalist id="fleet-packages">${[...new Set(fleet.assets.flatMap(a=>a.components.filter(c=>!c.runtime).map(c=>c.name)))].sort().map(n=>`<option value="${esc(n)}"></option>`).join('')}</datalist></label><label>Name match<select id="fleet-match">${option('exact','Exact name',request.match)}${option('contains','Contains text',request.match)}</select></label>`}<label>Version condition<select id="fleet-operator">${operators.map(o=>option(o.id,o.label,request.operator)).join('')}</select></label><label>Threshold version<input id="fleet-target" value="${esc(request.target)}" placeholder="e.g. 3.11" ${request.operator==='any'?'disabled':''}></label><button class="button primary" type="submit">Find deployed versions →</button></div></form><div class="version-presets"><span>Try a question</span>${btn('Python &lt; 3.11','data-fleet-preset="python"')}${btn('Node.js &lt; 20','data-fleet-preset="node"')}${btn('Log4j · all versions','data-fleet-preset="log4j"')}${btn('requests &lt; 2.32','data-fleet-preset="requests"')}</div>`;}
  function searchView(){return banner()+scopes()+panel('Find a runtime or library',searchForm())+`<div id="fleet-results" aria-live="polite">${draft?'<div class="panel empty">Search changed. Select “Find deployed versions” to refresh results.</div>':searchResults()}</div>`;}
  function searchResults(){
    const r=result();if(r.error)return panel('Check the query',`<p class="risk" role="alert">${esc(r.error)}</p>`);
    const rows=r.rows.filter(x=>status==='all'||x.status===status);page=Math.min(page,Math.max(0,Math.ceil(rows.length/50)-1));
    const needsReview=r.unknown>0;
    return statGrid([['Workloads in scope',r.assets.length,`${r.notRecorded.length} have no matching component record`,'⬡'],['Condition matched',r.matched,'Component occurrences across assets','✓'],['Other versions',r.other,'Recorded versions outside the condition','⇄'],['Unknown / incomplete',r.unknown,'Evidence gaps, version families or missing versions','?']])+panel(`Results · ${esc(queryLabel())}`,`<p class="version-summary ${needsReview?'needs-review':''}">${r.matched?`${r.matched} recorded component occurrence(s) match this query across ${new Set(r.rows.filter(x=>x.status==='match').map(x=>x.asset.app?.id)).size} application(s).`:'No exact recorded versions match this condition.'} ${r.unknown?`${r.unknown} observation(s) need review; incomplete records cannot establish absence.`:''} ${r.notRecorded.length?`${r.notRecorded.length} inventoried workloads have no matching component record.`:''}</p><div class="version-tabs" role="group" aria-label="Version result groups">${[['all','All observations',r.rows.length],['match','Matches',r.matched],['other','Other versions',r.other],['unknown','Unknown',r.unknown]].map(([id,label,n])=>btn(`${label} <span>${n}</span>`,`data-fleet-status="${id}" aria-pressed="${status===id}"`,status===id?'selected':'')).join('')}</div><div class="table-wrap"><table class="deployed-table"><thead><tr><th>Application / service</th><th>Environment</th><th>Component / exact version</th><th>Evidence</th><th>AWS asset</th><th>Trace</th></tr></thead><tbody>${rows.slice(page*50,page*50+50).map(row=>{
      const a=row.asset;return `<tr><td><strong>${esc(a.app?.name||'Unassigned application')}</strong><small>${esc(a.service)}</small></td><td>${tag(envName(a.environment),a.environment==='prod'?'prod':'')}</td><td><strong>${esc(row.component?.name||(request.kind==='runtime'?runtimes.find(x=>x.id===request.runtime)?.label:request.name))} <span class="exact-version">${esc(row.version||'Unknown')}</span></strong><small>${tag(row.status==='match'?'Matches':row.status==='other'?'Other version':'Unknown',row.status==='unknown'?'medium':row.status==='other'?'unknown':'')} ${row.component?.precision==='family'?'Version family only':''}</small></td><td>${tag(row.component?.precision==='family'?'Managed runtime family':describeEvidence(a),a.coverage==='gap'||row.component?.precision==='family'?'medium':a.coverage==='host'?'unknown':'')}<small>${esc(row.component?.precision==='family'?row.reason:a.coverage==='host'?'Installed software · application usage unverified':row.status==='unknown'?row.reason:row.source)}</small></td><td>${tag(a.kind)}<small>${esc(a.resourceId.split('/').at(-1).split(':').at(-1))}</small></td><td>${btn('Evidence →',`data-fleet-asset="${esc(a.id)}"`)}</td></tr>`;
    }).join('')||'<tr><td colspan="6" class="empty">No observations in this result group. Missing inventory is shown under Unknown.</td></tr>'}</tbody></table></div><div class="pager"><span>${rows.length} observation(s) · page ${page+1} of ${Math.max(1,Math.ceil(rows.length/50))}</span><button class="button" id="fleet-prev" ${page===0?'disabled':''}>Previous</button><button class="button" id="fleet-next" ${(page+1)*50>=rows.length?'disabled':''}>Next</button><button class="button" id="fleet-csv" ${!r.rows.length?'disabled':''}>↓ Export results</button></div><p class="footnote">Digest-linked SBOM means the observed AWS artifact identity matches the captured build manifest and SBOM job. It is an inventory correlation, not a live process attestation. EC2 observations describe installed packages. Lambda runtime families do not establish an exact patch.</p><details><summary>Workloads with no matching component record · ${r.notRecorded.length}</summary><p class="footnote">These workloads have inventory, but this component is not listed. An SBOM may be incomplete.</p><div class="detail-list">${r.notRecorded.map(a=>btn(`${esc(a.service)} · ${envName(a.environment)}`,`data-fleet-asset="${esc(a.id)}"`,'')).join('')}</div></details>`,`<a class="text-link" href="#matrix">Compare environments ↗</a>`);
  }
  function matrixView(){
    const r=environmentMatrix(fleet,request);
    return banner()+scopes(true)+panel('Component to compare',searchForm())+`<div id="fleet-results">${draft?'<div class="panel empty">Search changed. Select “Find deployed versions” to refresh the matrix.</div>':r.error?panel('Check the query',`<p role="alert" class="risk">${esc(r.error)}</p>`):panel(`Environment matrix · ${esc(queryLabel())}`,`<p class="section-note">All environments for the selected application and service scope. Multiple versions in one cell indicate coexisting versions; this can occur during a rollout.</p><div class="table-wrap"><table class="environment-matrix"><thead><tr><th>Application / service</th>${environmentOrder.map(e=>`<th>${envName(e)}</th>`).join('')}</tr></thead><tbody>${r.groups.map(g=>`<tr><td><strong>${esc(g.service)}</strong><small>${esc(g.app?.name||'Unassigned application')}</small></td>${environmentOrder.map(e=>{const cell=g.cells[e];return `<td>${!cell?'<span class="subtle">No assets</span>':`<div class="matrix-versions">${cell.versions.map(v=>{const matches=cell.rows.some(x=>x.version===v&&x.status==='match');return tag(v,matches?'':'unknown')}).join(' ')}${cell.rows.filter(x=>x.component?.precision==='family').length?tag([...new Set(cell.rows.filter(x=>x.component?.precision==='family').map(x=>x.version))].join(', ')+' · family','medium'):''}</div>${cell.mixed?tag('Mixed versions','medium'):''}${cell.unknown?`<small class="risk">${cell.unknown} incomplete observation(s)</small>`:''}${!cell.rows.length?'<small>Component not recorded</small>':''}<small>${cell.assets.length} workload(s)${cell.assets.some(a=>a.coverage==='host')?' · host inventory':''}</small>${btn('Inspect assets →',`data-fleet-cell="${esc(g.key)}" data-env="${e}"`)}`}</td>`}).join('')}</tr>`).join('')||'<tr><td colspan="4" class="empty">No matching component observations. Try another runtime or package.</td></tr>'}</tbody></table></div><p class="footnote">Green version tags match the selected condition; gray versions do not. Version families and evidence gaps stay visible. Cross-environment version differences are descriptive, not a compliance judgment.</p>`)}</div>`;
  }
  function sourceData(){return source==='servicenow'?fleet.snapshot.servicenow:source==='gitlab'?fleet.snapshot.gitlab:source==='aws'?fleet.snapshot.aws:{buildManifests:fleet.snapshot.buildManifests,sbomArtifacts:fleet.snapshot.sbomArtifacts,scenarios:fleet.snapshot.scenarios};}
  function sourcesView(){return banner()+`<div class="source-cards"><article><span class="source-logo">SN</span><h2>ServiceNow</h2><p>Business applications & ownership</p><strong>${fleet.apps.length} applications</strong><small>cmdb_ci_business_app · Table API shape</small></article><article><span class="source-logo gitlab">GL</span><h2>GitLab</h2><p>Projects, builds & environments</p><strong>${fleet.projectMap.size} projects · ${fleet.snapshot.gitlab.pipelines.length} pipelines</strong><small>Projects, Jobs, Environments, Deployments</small></article><article><span class="source-logo aws">AWS</span><h2>AWS</h2><p>Observed deployed workloads</p><strong>${fleet.assets.length} running workloads</strong><small>ECS DescribeTasks · Lambda GetFunction · EC2 / SSM</small></article></div>`+panel('How the records connect',`<div class="join-flow"><div><b>Business application</b><span>sys_id & custom project mapping</span></div><i>→</i><div><b>GitLab build</b><span>Project + commit + job artifact</span></div><i>→</i><div><b>AWS deployment</b><span>Observed digest or code hash</span></div><i>→</i><div><b>Exact component version</b><span>SBOM bound to that artifact</span></div></div><p class="footnote">The <code>u_gitlab_project_ids</code> field, AWS application/project/environment tags, and build manifest are explicit demo correlation conventions. They are not automatic relationships provided by these vendors. A mutable image tag or the latest GitLab pipeline is never used as version evidence. EC2 uses installed-software inventory; Lambda’s managed runtime patch remains unknown.</p>`)+panel('Inspect the simulated snapshots',`<div class="version-tabs" role="group" aria-label="Source snapshots">${[['servicenow','ServiceNow'],['gitlab','GitLab'],['aws','AWS'],['correlations','Build manifests & SBOMs']].map(([id,label])=>btn(label,`data-source-tab="${id}"`,source===id?'selected':'')).join('')}</div><div class="toolbar"><span class="subtle">Synthetic snapshot · ${esc(fleet.snapshot.snapshot_at)}</span>${btn('↓ Download this source','id="download-source"','button')}${btn('↓ Download full fixture','id="download-fixture"','button')}${btn(sourceRaw?'Hide JSON':'Show JSON','id="toggle-source"','button')}</div><p class="section-note">${source==='servicenow'?'API-shaped Table API records include sys_id, number, name, business criticality, application manager, and the custom project-ID mapping.':source==='gitlab'?'Captured project-scoped responses are aggregated with project_id context. Job artifacts contain the synthetic CycloneDX documents.':source==='aws'?'ECS task containers include observed image digests. Lambda configuration includes a code hash and managed runtime family. EC2 software inventory comes from SSM AWS:Application records.':'These are build-produced demo manifests and captured SBOM job artifact bodies, not a native GitLab REST response. The manifest binds a build job to an immutable deployment subject.'}</p>${sourceRaw?`<pre>${esc(JSON.stringify(sourceData(),null,2))}</pre>`:''}`)+panel('Included simulation scenarios',`<div class="scenario-grid">${fleet.snapshot.scenarios.map(s=>`<div><span class="scenario-dot"></span><p>${esc(s.description)}</p></div>`).join('')}</div><p class="footnote">No credentials are used. All API identities, accounts, projects, ARNs, digests, owners, and SBOMs are fictional. The snapshot is fixed, not live.</p>`)+panel('Evidence gaps to explore',assetTable(fleet.assets.filter(a=>a.coverage==='gap')));}
  function inspectAsset(id){
    const a=fleet.assets.find(x=>x.id===id);if(!a)return;
    const m=a.manifest;
    openDialog(`<div class="eyebrow">SIMULATED DEPLOYMENT EVIDENCE</div><h2 style="margin:12px 0">${esc(a.service)}</h2><p>${tag(envName(a.environment),a.environment==='prod'?'prod':'')} ${tag(a.kind)} ${tag(describeEvidence(a),a.coverage==='gap'?'medium':'')}</p><div class="lineage-steps"><div><span>01 · SERVICENOW</span><b>${esc(a.app?.name||'Application mapping missing')}</b><small>${esc(a.app?.number||'No business application tag')}</small></div><div><span>02 · GITLAB</span><b>${esc(a.project?.path_with_namespace||'Project mapping missing')}</b><small>${m?`Pipeline ${m.pipeline_id} · SBOM job ${m.sbom_job_id}`:a.kind==='EC2'?'Host inventory; no build-to-process correlation':'Build cannot be resolved'}</small></div><div><span>03 · AWS</span><b>${esc(a.resourceId)}</b><small>Observed ${esc(a.observedAt)} · ${esc(a.region)}</small></div></div><h3>Observed immutable artifact identity</h3><pre>${esc(a.digest||'No immutable artifact identity supplied')}</pre>${m?`<div class="meta"><div><label>OBSERVED BUILD COMMIT</label><span>${esc(m.commit_sha)}</span></div><div><label>GITLAB ENVIRONMENT TARGET</label><span>${esc(a.deployment?.sha||'Not supplied')}</span></div></div>`:''}${a.issues.length?`<div class="callout warning">${a.issues.map(esc).join('<br>')}</div>`:''}<h3>Recorded runtimes and libraries</h3><div class="table-wrap"><table><thead><tr><th>Component</th><th>Version</th><th>Evidence scope</th></tr></thead><tbody>${a.components.map(c=>`<tr><td>${esc(c.name)}</td><td>${esc(c.version||'Not supplied')}${c.precision==='family'?' (family only)':''}</td><td>${esc(c.origin)}</td></tr>`).join('')||'<tr><td colspan="3">No component inventory linked.</td></tr>'}</tbody></table></div><p class="footnote">${a.kind==='Lambda'?'AWS supplies a managed runtime family. Code SBOMs establish library versions, not the managed runtime patch.':a.kind==='EC2'?'SSM records exact installed package versions. An application tag alone does not establish which version the running process uses.':'The image digest links this observed container to the build manifest and captured SBOM. This is inventory evidence, not a live process measurement.'}</p>${a.bom?btn('Open this build’s SBOM →','id="inspect-asset-sbom"','button primary'):''}<details><summary>Raw source records and correlation manifest</summary><pre>${esc(JSON.stringify({servicenow:a.app?.raw||null,gitlab:{project:a.project,pipeline:a.pipeline,job:a.job,deployment:a.deployment},buildManifest:m,aws:a.raw,ssm:a.inventory||null},null,2))}</pre></details>`);
    document.querySelector('#inspect-asset-sbom')?.addEventListener('click',()=>inspectSbom(a.bom,`${a.service}-${a.environment}.cdx.json`,`${a.app?.name} · ${envName(a.environment)} · ${a.service} · ${shortDigest(a.digest)}`));
  }
  function exportRows(){
    const r=result();if(r.error)return;
    const rows=lastView==='applications'||lastView==='sources'?selectAssets(fleet,request).map(a=>({application:a.app?.name||'Unassigned',applicationId:a.app?.id||'',environment:a.environment,service:a.service,resourceType:a.kind,asset:a.resourceId,evidence:describeEvidence(a),digest:a.digest,project:a.project?.id||'',commit:a.manifest?.commit_sha||'',issues:a.issues.join('; '),snapshot:fleet.snapshot.snapshot_at})):queryPortfolio(fleet,lastView==='matrix'?{...request,environment:'all'}:request).rows.map(r=>({application:r.asset.app?.name||'Unassigned',applicationId:r.asset.app?.id||'',environment:r.asset.environment,service:r.asset.service,component:r.component?.name||'',version:r.version,precision:r.component?.precision||'unknown',condition:request.operator,threshold:request.operator==='any'?'':request.target,status:r.status,reason:r.reason,evidence:r.component?.origin||describeEvidence(r.asset),resourceType:r.asset.kind,asset:r.asset.resourceId,project:r.asset.project?.id||'',commit:r.asset.manifest?.commit_sha||'',pipeline:r.asset.manifest?.pipeline_id||'',sbomJob:r.asset.manifest?.sbom_job_id||'',digest:r.asset.digest,snapshot:fleet.snapshot.snapshot_at}));
    if(!rows.length)return;const keys=Object.keys(rows[0]),quote=v=>'"'+String(v??'').replace(/^[=+@\-\t\r]/,"'$&").replace(/"/g,'""')+'"';download([keys.map(quote).join(','),...rows.map(r=>keys.map(k=>quote(r[k])).join(','))].join('\r\n'),'simulated-deployment-evidence.csv','text/csv');
  }
  function download(text,name,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  function readQuery(){const value=id=>document.querySelector(id)?.value;request={...request,kind:value('#fleet-component-kind')||request.kind,runtime:value('#fleet-runtime')||request.runtime,name:value('#fleet-name')??request.name,match:value('#fleet-match')||request.match,operator:value('#fleet-operator')||request.operator,target:value('#fleet-target')??request.target};}
  function preset(name){request={...request,kind:name==='log4j'||name==='requests'?'package':'runtime',runtime:name==='node'?'node':'python',name:name==='log4j'?'log4j-core':name==='requests'?'requests':request.name,operator:name==='log4j'?'any':'lt',target:name==='node'?'20':name==='requests'?'2.32':'3.11',match:'exact'};draft=false;status='all';page=0;if(!['deployed','matrix'].includes(lastView))location.hash='deployed';else onChange();}
  function bind(view){
    lastView=view;if(!fleet)return;const $=s=>document.querySelector(s);
    for(const [id,key]of [['#fleet-app','appId'],['#fleet-env','environment'],['#fleet-project','projectId'],['#fleet-kind','kindFilter']])$(id)?.addEventListener('change',e=>{readQuery();request[key]=e.target.value;if(key==='appId')request.projectId='all';page=0;draft=false;onChange()});
    const form=$('#fleet-query');if(form){form.onsubmit=e=>{e.preventDefault();readQuery();draft=false;page=0;status='all';onChange()};const invalidate=()=>{draft=true;$('#fleet-results').innerHTML='<div class="panel empty">Search changed. Select “Find deployed versions” to refresh results.</div>'};form.oninput=invalidate;form.onchange=invalidate;$('#fleet-component-kind').addEventListener('change',()=>{readQuery();draft=true;onChange()});$('#fleet-operator').addEventListener('change',()=>{$('#fleet-target').disabled=$('#fleet-operator').value==='any'});}
    document.querySelectorAll('[data-fleet-preset]').forEach(b=>b.onclick=()=>preset(b.dataset.fleetPreset));
    document.querySelectorAll('[data-fleet-app]').forEach(b=>b.onclick=()=>{request.appId=b.dataset.fleetApp;request.projectId='all';draft=false;location.hash='deployed'});
    document.querySelectorAll('[data-fleet-asset]').forEach(b=>b.onclick=()=>inspectAsset(b.dataset.fleetAsset));
    document.querySelectorAll('[data-fleet-status]').forEach(b=>b.onclick=()=>{status=b.dataset.fleetStatus;page=0;onChange()});
    document.querySelectorAll('[data-fleet-cell]').forEach(b=>b.onclick=()=>{const g=environmentMatrix(fleet,request).groups.find(g=>g.key===b.dataset.fleetCell);openDialog(`<h2>${esc(g.service)} · ${envName(b.dataset.env)}</h2><p class="subtle">Select a workload to trace its evidence.</p>${assetTable(g.cells[b.dataset.env].assets)}`);document.querySelectorAll('#details [data-fleet-asset]').forEach(x=>x.onclick=()=>inspectAsset(x.dataset.fleetAsset))});
    $('#fleet-prev')?.addEventListener('click',()=>{page--;onChange()});$('#fleet-next')?.addEventListener('click',()=>{page++;onChange()});$('#fleet-csv')?.addEventListener('click',exportRows);
    document.querySelectorAll('[data-source-tab]').forEach(b=>b.onclick=()=>{source=b.dataset.sourceTab;onChange()});$('#toggle-source')?.addEventListener('click',()=>{sourceRaw=!sourceRaw;onChange()});$('#download-source')?.addEventListener('click',()=>download(JSON.stringify(sourceData(),null,2),`simulated-${source}.json`));$('#download-fixture')?.addEventListener('click',()=>download(JSON.stringify(fleet.snapshot,null,2),'simulated-enterprise.json'));
  }
  return {
    async load(){try{const response=await fetch(new URL('../data/simulated-enterprise.json',import.meta.url));if(!response.ok)throw Error(`Snapshot request failed (${response.status})`);fleet=buildPortfolio(await response.json());}catch(e){error=e.message;}finally{loading=false;onChange();}},
    render(view){lastView=view;if(loading)return '<section class="panel empty" role="status">Loading the simulated application portfolio…</section>';if(error)return `<section class="panel"><p class="risk" role="alert">Unable to load simulation: ${esc(error)}</p><p>Reload the page to retry. The standalone SBOM views remain available.</p></section>`;return ({applications,deployed:searchView,matrix:matrixView,sources:sourcesView})[view]();},
    bind,export:exportRows,
  };
}
